Translate("zhCN", "loch-modan", {
	title = "洛克莫丹",
	sections = {
		{
			title = "概述",
			text = [=[洛克莫丹是卡兹莫丹境内一片开阔的盆地，丘陵起伏，松林遍布，位于{link:dun-morogh}丹莫罗{/link}以东。它的中心是{link:the-loch}洛克湖{/link}，这片土地便因这座大湖而得名，湖的北端由{link:stonewrought-dam}巨石水坝{/link}拦住。{link:thelsamar}塞尔萨玛{/link}镇坐落在湖的西岸附近。矮人的塔楼扼守着各处山口：向西通往{link:ironforge}铁炉堡{/link}，向北通往{link:wetlands}湿地{/link}，向南通往{link:searing-gorge}灼热峡谷{/link}。比起丹莫罗的冰雪，这里的土地温和得多，矿石、猎物和鱼类都很丰富，{link:kingdom-of-ironforge}铁炉堡王国{/link}的{link:dwarves}矮人{/link}长久以来一直视之为自己的领土。]=],
		},
		{
			title = "起源",
			text = [=[没有编年史记载{link:dwarves}矮人{/link}何时最初定居在{link:the-loch}洛克湖{/link}畔，也没有记载{link:stonewrought-dam}巨石水坝{/link}建于何时。在他们的历史中，这片土地由来已久。在{link:valley-of-kings}国王谷{/link}，两座巨大的雕像守望着南方的道路。它们纪念的是玛多兰·铜须和卡德罗斯·蛮锤，这两人在三锤之战的时代率领着各自的氏族。据说，他们的儿子在那场战争之后立起了这两座雕像，守望通往南方的道路，警告任何胆敢再次进犯矮人国度的人。]=],
		},
		{
			title = "当今",
			text = [=[洛克莫丹正处于围困之中，而守卫者寥寥无几。{link:ironforge}铁炉堡{/link}预备队已被调往遥远的前线为{link:alliance}联盟{/link}作战，许诺给{link:the-loch}洛克湖{/link}的援军从未到来。{link:captain-rugelfuss}拉格弗斯上尉{/link}仅凭一个团守着{link:valley-of-kings}国王谷{/link}，而{link:stonesplinter-troggs}碎石怪部族{/link}的{link:troggs}石腭怪{/link}从南方的丘陵中蜂拥而出，攻占了湖边{link:explorers-league}探险者协会{/link}的挖掘场。{link:mo-grosh-ogres}莫格罗什氏族{/link}的{link:ogres}食人魔{/link}从东北方袭来。{link:kobolds}狗头人{/link}占据了{link:silver-stream-mine}银泉矿洞{/link}。最糟糕的是，{link:dark-iron-dwarves}黑铁{/link}破坏者已悄悄摸到了水坝跟前，而且他们在{link:dwarves}矮人{/link}信任的人当中还有朋友。在{link:thelsamar}塞尔萨玛{/link}，{link:magistrate-bluntnose}镇长埃罗恩·钝鼻{/link}被告知，他必须等上几个月才能得到寥寥几名士兵。他已不再等待，他用足色的{link:ginro-hearthkindle}金{/link}币雇佣任何愿意作战的陌生人。]=],
		},
		{
			title = "居民",
			text = [=[• {b}{link:ironforge}铁炉堡{/link}的{link:dwarves}矮人{/link}。{/b}巡山人、矿工、渔夫和厨师住在{link:thelsamar}塞尔萨玛{/link}，并驻守在沿山口而建的塔楼中。
• {b}探险者协会。{/b}{link:explorers-league}探险者协会{/link}从它在塞尔萨玛的分部为{link:prospector-ironband}勘察员基恩萨·铁环{/link}在湖东废墟中的挖掘场提供补给。
• {b}{link:the-farstrider-lodge}旅行者营地{/link}的猎手。{/b}矮人、{link:humans}人类{/link}和一位{link:high-elves}高等精灵{/link}在东部丘陵中经营着一座猎人小屋。
• {b}{link:stonesplinter-troggs}碎石怪石腭怪{/link}。{/b}他们占据着南部的{link:stranglethorn-vale}山谷{/link}、{link:the-loch}洛克湖{/link}的岛屿和挖掘场的废墟。
• {b}{link:mo-grosh-ogres}莫格罗什食人魔{/link}。{/b}一个{link:ogres}食人魔{/link}氏族在东北部的洞穴中建起了据点。
• {b}{link:tunnel-rat-kobolds}坑道鼠狗头人{/link}。{/b}{link:kobolds}狗头人{/link}在西部山麓挖了巢穴，并占满了{link:silver-stream-mine}银泉矿洞{/link}。
• {b}{link:dark-iron-dwarves}黑铁矮人{/link}。{/b}工兵和叛乱者潜伏在水坝周围，至少有一名他们的密探藏身于矮人自己的搬运工之中。]=],
		},
		{
			title = "历史",
			text = [=[• {b}三锤。{/b}三大氏族之战结束后，铜须与蛮锤的国王被铭刻在{link:the-loch}洛克湖{/link}南门的石像之中。
• {b}第二次战争。{/b}在{link:second-war}第二次战争{/link}中，{link:horde}部落{/link}席卷卡兹莫丹，湖区落入{link:orcs}兽人{/link}的统治。{link:dwarves}矮人{/link}夺回了这里，但兽人投石车和货车的残骸至今仍躺在浅水中和古老的银矿后面。
• {b}挖掘。{/b}{link:explorers-league}探险者协会{/link}在洛克湖东南的古代废墟中开设了一处挖掘场。挖掘者找到了一些奇异的石雕神像，不久之后，{link:troggs}石腭怪{/link}便从地下钻了出来。
• {b}当今。{/b}如今守卫洛克湖的，只有留下来的少数人，以及他们能雇来的任何帮手。]=],
		},
		{
			title = "洛克湖传说",
			text = [=[• {link:thelsamar}塞尔萨玛{/link}以血肠闻名：把熊肉塞进野猪肠衣，再用蜘蛛的体液调味。厨师坚称，做起来比看上去难。
• {link:the-loch}洛克湖{/link}的鳄鱼因皮和肉而备受珍视，但它们盘踞在湖中的岛屿上，很少有猎手能毫发无伤地把它们拿下。
• 洛克湖的巡山人喝的是在遥远的{link:brewnall-village}烈酒村{/link}酿造的微光酒。一个尝过的人发誓，喝下后四肢轻盈得仿佛能飞起来。
• {link:south-gate-pass}南门小径{/link}终年积雪，尽管下方的洛克湖岸一片青绿。]=],
		},
	},
})

Translate("zhCN", "thelsamar", {
	title = "塞尔萨玛",
	aliases = { "烈酒旅店" },
	sections = {
		{
			title = "概述",
			text = [=[塞尔萨玛是{link:loch-modan}洛克莫丹{/link}的主要城镇，一片聚集在湖西岸附近的石屋。它的中心是烈酒旅店，镇上从不缺饥肠辘辘的工人和奔跑的孩子。这里有一座锻炉、一处狮鹫栖木和{link:explorers-league}探险者协会{/link}的一个分部，街上还挂着一张通缉某个{link:ogres}食人魔{/link}酋长的告示。{link:mountaineer-kadrell}巡山人卡德雷尔{/link}在穿镇而过的道路上巡逻，{link:magistrate-bluntnose}镇长埃罗恩·钝鼻{/link}维持着镇上的秩序。塞尔萨玛缺少{link:ironforge}铁炉堡{/link}的许多便利：镇上的铁匠总是缺青铜，他希望有商人能把煤运到镇上来。]=],
		},
	},
})

Translate("zhCN", "stonewrought-dam", {
	title = "巨石水坝",
	sections = {
		{
			title = "概述",
			text = [=[巨石水坝封住了{link:the-loch}洛克湖{/link}的北端，那是一道巨大的{link:dwarves}矮人{/link}石墙，整座湖都倚靠着它。{link:chief-engineer-hinderweir-vii}主工程师辛德维尔七世{/link}和几名工程师、巡山人一起看守着它。它的大部分守卫都已被派往前线，包括它的首席检查员。这份损失让人感受深切。{link:dark-iron-dwarves}黑铁矮人{/link}已经摧毁了{link:thandol-span}萨多尔大桥{/link}，洗劫了北方的{link:dun-modr}丹莫德{/link}，辛德维尔确信下一个目标就是水坝。有人在水坝东侧的坡道上看见了他们的工兵。]=],
		},
	},
})

Translate("zhCN", "algaz-station", {
	title = "奥加兹岗哨",
	aliases = { "北部哨塔" },
	sections = {
		{
			title = "概述",
			text = [=[奥加兹岗哨是{link:loch-modan}洛克莫丹{/link}北部的守卫哨所。它的塔楼矗立在北门小径的隧道从{link:dun-morogh}丹莫罗{/link}下来的地方，就在通往{link:wetlands}湿地{/link}的山口{link:dun-algaz}丹奥加兹{/link}以南。许多巡山人驻扎在这里。{link:mountaineer-stormpike}巡山人雷矛{/link}在塔顶眺望着各条道路，乐于讲述自己的英勇事迹。一名护甲商和一名行商为守军服务。在{link:morgan-s-vigil}岗哨{/link}以北，守卫丹奥加兹的巡山人发现前方的道路上满是{link:orcs}兽人{/link}。]=],
		},
	},
})

Translate("zhCN", "silver-stream-mine", {
	title = "银泉矿洞",
	sections = {
		{
			title = "概述",
			text = [=[银泉矿洞位于{link:loch-modan}洛克莫丹{/link}北部，在{link:algaz-station}奥加兹岗哨{/link}与水坝之间。在枯竭之前，它为{link:dwarves}矮人{/link}出产了多年的白银。后来矿工{link:alliance}联盟{/link}把它改成了仓库，里面堆满了一箱箱上好的矮人工具。如今{link:tunnel-rat-kobolds}坑道鼠狗头人{/link}搬了进来，把爪子伸向了所有东西。巡山人打算清理矿洞，但矿工联盟希望先把它的装备运出来，以免被士兵弄坏。]=],
		},
	},
})

Translate("zhCN", "ironband-s-excavation-site", {
	title = "铁环挖掘场",
	aliases = { "铁环挖掘场" },
	sections = {
		{
			title = "概述",
			text = [=[铁环挖掘场是{link:explorers-league}探险者协会{/link}在{link:the-loch}洛克湖{/link}东南古代废墟中的一处挖掘场。{link:prospector-ironband}勘察员基恩萨·铁环{/link}领导着它，{link:magmar-fellhew}麦格玛尔·落斧{/link}负责管理工作。挖掘者刚刚发掘出大量石雕神像，{link:stonesplinter-troggs}碎石怪石腭怪{/link}就从废墟中冒了出来，把他们赶走了。这些神像似乎会吸引{link:troggs}石腭怪{/link}，还会让其中一些陷入狂暴。挖掘者逃得太快，把大部分工具都丢下了。如今一名石腭怪酋长和他的萨满祭司统治着这处挖掘场。]=],
		},
	},
})

Translate("zhCN", "mo-grosh-stronghold", {
	title = "莫格罗什要塞",
	sections = {
		{
			title = "概述",
			text = [=[莫格罗什要塞是{link:the-loch}洛克湖{/link}东北丘陵中的一片洞穴群。一个{link:ogres}食人魔{/link}氏族在那里扎营，从那里出击，袭击{link:thelsamar}塞尔萨玛{/link}、水坝和挖掘场。他们在洞穴中开采稀有的水晶。不久前，他们伏击了一支从{link:wetlands}湿地{/link}来的矿石车队，把矿石搬进了自己的营地。他们的酋长{link:chok-sul}卓克苏尔{/link}正被塞尔萨玛的治安官通缉。]=],
		},
	},
})

Translate("zhCN", "the-farstrider-lodge", {
	title = "旅行者营地",
	aliases = { "旅行者营地" },
	sections = {
		{
			title = "概述",
			text = [=[旅行者营地坐落在{link:loch-modan}洛克莫丹{/link}的东部丘陵中。它高大的木梁和舒展的屋顶是精灵的风格，没有编年史记载是谁建造了它。如今它是一座猎人小屋，在这里，狩猎技艺被看得高于一切。{link:marek-ironheart}马雷克·铁心{/link}在这里经营鳄鱼皮和鳄鱼肉。一位{link:high-elves}高等精灵{/link}{link:vyrin-swiftwind}维林·疾风{/link}沉默寡言，一个名叫{link:daryl-the-youngling}达瑞尔{/link}的年轻{link:humans}人类{/link}则逢人便吹嘘。商人向前来狩猎的人出售弓和枪。]=],
		},
	},
})

Translate("zhCN", "valley-of-kings", {
	title = "国王谷",
	sections = {
		{
			title = "概述",
			text = [=[国王谷是{link:loch-modan}洛克莫丹{/link}的西南角，从{link:south-gate-pass}南门小径{/link}而来的道路在这里下行进入绿野。两座巨大的{link:dwarves}矮人{/link}国王雕像，玛多兰·铜须和卡德罗斯·蛮锤，矗立在{link:stranglethorn-vale}山谷{/link}之上，面朝南方。附近耸立着{link:captain-rugelfuss}拉格弗斯上尉{/link}的南部哨塔，他的团因为担心敌人入侵而不敢离开岗位。再往南，一道上锁的大门通往{link:searing-gorge}灼热峡谷{/link}，{link:mountaineer-pebblebitty}巡山人贝波蒂{/link}只为证明了自身价值的人打开它。]=],
		},
	},
})

Translate("zhCN", "the-loch", {
	title = "洛克湖",
	aliases = { "洛克湖" },
	sections = {
		{
			title = "概述",
			text = [=[洛克湖是卡兹莫丹的大湖，在群山之下静谧而寒冷。渔夫在它的西岸劳作，猎手们寻找盘踞在湖中岛屿上的鳄鱼。蛇颈龙在深处游弋。岛上并不安全：{link:troggs}石腭怪{/link}占据着其中最大的一座，一位{link:gnomes}侏儒{/link}飞行员在附近坠入湖中时，他们袭击了他。古老的残骸散落在浅水中，渔夫们至今仍会在碎片中找到失物。]=],
		},
	},
})

Translate("zhCN", "grizzlepaw-ridge", {
	title = "灰爪山",
	sections = {
		{
			title = "概述",
			text = [=[灰爪山耸立在{link:thelsamar}塞尔萨玛{/link}以南，位于城镇与西南方的{link:troggs}石腭怪{/link}地盘之间。它属于熊。它们的巢穴散布在山坡上，其中一头体型巨大的黑熊{link:ol-sooty}老黑炭{/link}也在此安家，{link:the-farstrider-lodge}旅行者营地{/link}的猎手们长久以来一直想要猎杀它，却始终未能成功。下方道路上的旅人都会留意山丘，因为这头老熊有时会下山来。]=],
		},
	},
})

Translate("zhCN", "stonesplinter-valley", {
	title = "碎石怪之谷",
	sections = {
		{
			title = "概述",
			text = [=[碎石怪之谷蜿蜒于{link:loch-modan}洛克莫丹{/link}西南部的群山之间，如今挤满{link:stranglethorn-vale}山谷{/link}的{link:troggs}石腭怪{/link}便以它为名。他们的斥候监视着道路，他们的先知和碎颅者占据着南部的丘陵，他们的酋长{link:grawmug}格劳姆格{/link}守在他们最深的洞穴里。在这片土地上巡逻的巡山人并不总能回来。{link:mountaineer-ylva}巡山人伊尔娃{/link}正是来到这里寻找一支这样失踪的巡逻队，也正是在这里倒下。]=],
		},
	},
})

Translate("zhCN", "south-gate-pass", {
	title = "南门小径",
	sections = {
		{
			title = "概述",
			text = [=[南门小径是{link:dun-morogh}丹莫罗{/link}与{link:loch-modan}洛克莫丹{/link}之间的南部隧道。它西起南门哨岗的塔楼，东至{link:valley-of-kings}国王谷{/link}，是从{link:ironforge}铁炉堡{/link}到{link:thelsamar}塞尔萨玛{/link}最近的道路。这条通道地势很高，终年积雪。{link:the-loch}洛克湖{/link}的一位萨满祭司曾派人取一罐这里的雪，用于一项他没有解释的法术。巡山人从丹莫罗经由这里运送一桶桶黑啤。]=],
		},
	},
})

Translate("zhCN", "captain-rugelfuss", {
	title = "拉格弗斯上尉",
	subtitle = "南部哨塔的上尉",
	found = "国王谷，南部哨塔",
	hint = "与守卫南部哨塔的上尉交谈。",
	allegiance = "铁炉堡王国 · 铁炉堡巡山人",
	aliases = { "鲁格弗斯" },
	sections = {
		{
			title = "概述",
			text = [=[拉格弗斯上尉统领着守卫{link:loch-modan}洛克莫丹{/link}南门的团，驻守在{link:valley-of-kings}国王谷{/link}雕像下方的塔楼里。他没有耐心接受敬礼。他说，{link:alliance}联盟{/link}在海外处境艰难，这让{link:dwarves}矮人{/link}的土地愈发珍贵，而从这片土地中涌出的{link:troggs}石腭怪{/link}对国王是严重的威胁。]=],
		},
		{
			title = "意义",
			text = [=[鲁格弗斯是那个被留下来守门的士兵。{link:ironforge}铁炉堡{/link}预备队已被调往前线，他手下寥寥无几的巡山人一旦离开大门，就会招来入侵。于是他用唯一剩下的方式与{link:troggs}石腭怪{/link}作战：派志愿者代替他进入山中。]=],
		},
		{
			title = "事迹",
