Translate("zhCN", "chief-engineer-hinderweir-vii", {
	title = "主工程师辛德维尔七世",
	subtitle = "巨石水坝的看守者",
	found = "巨石水坝顶上",
	hint = "与守望水坝的总工程师交谈。",
