	aliases = { "辛德维尔" },
	sections = {
		{
			title = "概述",
			text = [=[主工程师辛德维尔七世看守着{link:stonewrought-dam}巨石水坝{/link}，那是一道拦住{link:the-loch}洛克湖{/link}的巨大石墙。他是以这个名字担任这一职务的第七人，没有编年史记载他之前的六位。他是一个忧心忡忡的{link:dwarves}矮人{/link}，而他有理由如此。他最好的检查员和大部分守卫都被派往了{link:alliance}联盟{/link}前线，而{link:dark-iron-dwarves}黑铁矮人{/link}正在北方活动。]=],
		},
		{
			title = "意义",
			text = [=[辛德维尔看到了别人忽略的规律。先是{link:thandol-span}萨多尔大桥{/link}被摧毁，然后{link:dun-modr}丹莫德{/link}遭到洗劫。他毫不怀疑，水坝就是{link:dark-iron-dwarves}黑铁氏族{/link}的下一个目标，而如果水坝倒塌，{link:the-loch}洛克湖{/link}也将随之陷落。]=],
		},
		{
			title = "事迹",
			text = [=[• 他以单薄的守卫看守着{link:stonewrought-dam}巨石水坝{/link}。
• 他把一份{link:dark-iron-dwarves}黑铁{/link}火药样本送给{link:dun-modr}丹莫德{/link}的爆破专家。
• 他调制了从黑铁炸药下拯救水坝的混合剂。]=],
		},
	},
	chapters = {
		{
			title = "坡道上的线索",
			hint = "在水坝东侧坡道上搜寻黑铁矮人的踪迹。",
			text = [=[有人在水坝东侧的坡道上看见了{link:dark-iron-dwarves}黑铁{/link}工兵。他们留下的东西中有一桶气味古怪的粉末。辛德维尔判断这是某种炸药，于是把一份样本向北经由奥加兹大门送给{link:dun-modr}丹莫德{/link}驻军的火药大师{link:ashlan-stonesmirk}阿什兰·暗石{/link}，并嘱咐送信人走大路。]=],
		},
		{
			title = "爆盐",
			hint = "查明黑铁火药的真实身份。",
			text = [=[石笑凭银色的晶体和气味认出了这种粉末：爆盐。干燥时它是无害的。一旦受潮，它足以把一座山炸开。他送回了一份解除药剂，并告知还需要什么：山中潜伏蜘蛛的毒液、一滴鳄鱼的眼泪，以及一块{link:mo-grosh-ogres}莫格罗什食人魔{/link}所开采的那种稀有水晶。]=],
		},
		{
			title = "水坝之下",
			hint = "拯救巨石水坝。",
			text = [=[混合剂还没准备好，辛德维尔就看到{link:dark-iron-dwarves}黑铁{/link}叛乱者带着一个大桶向水坝游去，而手边没有一个巡山人能阻止他们。炸药放在水坝底部的水下，混合剂及时被搅了进去。水坝得救了。辛德维尔并不假装它从此一劳永逸。]=],
		},
	},
	mentions = {
		{ text = "黑暗的威胁：坡道上的工兵" },
		{ text = "黑暗的威胁：古怪的粉末" },
		{ text = "黑暗的威胁：前往{link:dun-modr}丹莫德{/link}之路" },
		{ text = "黑暗的威胁：解除药剂" },
		{ text = "黑暗的威胁：三种材料" },
		{ text = "黑暗的威胁：水下的炸药桶" },
		{ text = "黑暗的威胁：水坝得救" },
	},
	bonds = {
		{ id = "ashlan-stonesmirk", name = "阿什兰·暗石", note = "丹莫德的爆破专家" },
		{ id = "chok-sul", name = "卓克苏尔", note = "他的食人魔持有那些水晶" },
	},
})

Translate("zhCN", "prospector-ironband", {
	title = "勘察员基恩萨·铁环",
	subtitle = "探险者协会的勘察员",
