		},
		{
			title = "意义",
			text = [=[铁环是一位实地工作的学者。他相信挖掘场的石雕神像或许能揭示{link:troggs}石腭怪{/link}与{red:titans}泰坦{/red}之间的联系，他从{link:loch-modan}洛克莫丹{/link}一路追寻这个问题直到{link:badlands}废土{/link}。他的发现会传到{link:ironforge}铁炉堡{/link}的{link:explorers-league}探险者协会{/link}。]=],
		},
		{
			title = "事迹",
			text = [=[• 他领导挖掘工作，并为协会撰写报告。
• 他一再索要那些已经寄出却从未送达的炸药粉。
• 他派人打听勘察员阿戈莫德的消息，后者曾领导协会在{link:badlands}废土{/link}的挖掘。]=],
		},
	},
	chapters = {
		{
			title = "石雕神像",
			hint = "把勘察员的报告送到塞尔萨玛。",
			text = [=[铁环的报告简短而耐心。挖掘仍在继续，只是被比平时更具攻击性的{link:troggs}石腭怪{/link}拖慢了。大多数发现只是有趣而已。有一项却不然：石雕神像会把石腭怪吸引过来，还会让其中一些陷入狂暴。需要更多研究。还有，再问一次，他的炸药粉到底在哪儿？]=],
		},
		{
			title = "失踪的火药",
			hint = "护送火药安全抵达挖掘场。",
			text = [=[{link:jern-hornhelm}吉恩·角盔{/link}几周前就送出了火药，但它始终没有送到。下一批货由搬运工沿着{link:the-loch}洛克湖{/link}的弯道运送，途中{link:dark-iron-dwarves}黑铁矮人{/link}发动了袭击。搬运工之一塞安是他们的人，尽管他已与其他人共事了将近一年。当米兰终于把剩下的火药送到时，铁环为此高兴，但也为黑铁矮人竟有朋友能接触到这类东西而感到不安。]=],
		},
		{
			title = "阿戈莫德的命运",
			hint = "查明勘察员阿戈莫德在废土遭遇了什么。",
			text = [=[人们在{link:badlands}废土{/link}发现了阿戈莫德的尸体，残破不堪，被啃得一干二净，砂岩上有他亲手刻下的一个词：{link:murdaloc}莫达洛克{/link}。铁环哀悼他是一位头脑顽固、出手凶狠的斗士。他担心阿戈莫德的挖掘者找到的瓮唤醒了{link:troggs}石腭怪{/link}，就像他自己的神像一样。]=],
		},
	},
	mentions = {
		{ text = "挖掘进度报告" },
		{ text = "给铁环的火药" },
		{ text = "保护货物" },
		{ text = "挖掘工具：从废墟中找回" },
		{ text = "铁环需要你！" },
		{ text = "寻找阿戈莫德" },
		{ text = "{link:murdaloc}莫达洛克{/link}" },
		{ text = "阿戈莫德的命运" },
	},
	bonds = {
		{ id = "magmar-fellhew", name = "麦格玛尔·落斧", note = "管理他的挖掘场" },
		{ id = "jern-hornhelm", name = "吉恩·角盔", note = "他在塞尔萨玛的联络人" },
		{ id = "prospector-stormpike", name = "勘察员塔伯斯·雷矛", note = "从铁炉堡派人帮助他" },
		{ id = "stonesplinter-troggs", name = "碎石怪石腭怪", note = "占据着他的挖掘场" },
	},
})

